-- 세트 233: Job 과 CronJob 실습: 만들기, 로그 읽기, 실패 고치기, 병렬 실행, 정해진 때 실행과 멈추기
-- 명세: docs/specs/spec_k8s_job_cronjob_set.md. 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (233, 1, 'Job 만들어 한 번 실행하기', '`hello` 라는 이름의 Job 을 만드세요. 이미지는 `busybox:1.36`, 실행할 명령은 `echo hello etude` 입니다. Job 이 **성공으로 끝날 때까지** 확인하세요.', '`kubectl create job 이름 --image=이미지 -- 명령 ...` 처럼 `--` 뒤에 실행할 명령을 씁니다. 끝났는지는 `kubectl get jobs` 로 봐요.', 'kubectl create job hello --image=busybox:1.36 -n $NS -- echo hello etude
kubectl get jobs -n $NS
kubectl logs job/hello -n $NS

# Job 은 Pod 를 만들어 명령을 끝까지 한 번 실행하고, 성공하면 더 만들지 않는다
# Deployment 와 달리 끝나는 것이 정상이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ -n \\"$(kubectl get job hello -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" ] && kubectl get job hello -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null | grep -q \\"^busybox\\" ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get job hello -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 1 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( kubectl logs job/hello -n $NS 2>/dev/null | grep -q \\"^hello etude$\\" )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Job hello 가 busybox 이미지로 만들어졌다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get job hello -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" ] && kubectl get job hello -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null | grep -q \\"^busybox\\""]}, {"label": "Job 이 성공 1번으로 끝났다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get job hello -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 1 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "로그가 hello etude 이다", "cmd": ["sh", "-c", "kubectl logs job/hello -n $NS 2>/dev/null | grep -q \\"^hello etude$\\""]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 2, 'get jobs 의 COMPLETIONS 읽기', '지금 `hello` 와 `flaky` 두 Job 이 있습니다. **Job 목록**을 `/tmp/jobs.txt` 에 저장하고, COMPLETIONS 칸이 두 Job 에서 어떻게 다른지 확인해 보세요.', '`kubectl get jobs` 의 결과를 `>` 로 파일에 저장하고 `cat` 으로 읽어 보세요. COMPLETIONS 는 `성공한 수/필요한 수` 입니다.', 'kubectl get jobs -n $NS > /tmp/jobs.txt
cat /tmp/jobs.txt

# hello 는 1/1 (필요한 1번 중 1번 성공), flaky 는 0/1 (아직 한 번도 성공하지 못함)', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl create job hello --image=busybox:1.36 -n $NS -- echo hello-job >/dev/null 2>&1; kubectl wait --for=condition=complete job/hello -n $NS --timeout=90s >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: batch/v1\\nkind: Job\\nmetadata:\\n  name: flaky\\nspec:\\n  backoffLimit: 0\\n  template:\\n    spec:\\n      restartPolicy: Never\\n      containers:\\n      - name: main\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"ech0 done\\"]\\nEOF\\ni=0; while [ $i -lt 90 ]; do f=$(kubectl get job flaky -n $NS -o jsonpath=''{.status.failed}'' 2>/dev/null); [ \\"${f:-0}\\" -ge 1 ] && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( grep -q \\"^NAME\\" /tmp/jobs.txt ) && ( grep -Eq \\"^hello .*1/1\\" /tmp/jobs.txt ) && ( grep -Eq \\"^flaky .*0/1\\" /tmp/jobs.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Job 목록이 저장됐다", "cmd": ["sh", "-c", "grep -q \\"^NAME\\" /tmp/jobs.txt"]}, {"label": "hello 는 1/1 이다", "cmd": ["sh", "-c", "grep -Eq \\"^hello .*1/1\\" /tmp/jobs.txt"]}, {"label": "flaky 는 0/1 이다", "cmd": ["sh", "-c", "grep -Eq \\"^flaky .*0/1\\" /tmp/jobs.txt"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 3, 'logs job/이름 으로 결과 읽기', 'Job `hello` 가 처리를 끝냈습니다. **Job 의 로그**를 `/tmp/job-log.txt` 에 저장하고, 마지막에 처리한 티켓 번호가 무엇인지 확인하세요.', '`kubectl logs` 는 Pod 이름 대신 `job/이름` 으로도 읽을 수 있어요. 결과를 파일에 저장하고 `cat` 으로 읽어 보세요.', 'kubectl logs job/hello -n $NS > /tmp/job-log.txt
cat /tmp/job-log.txt

# Job 의 Pod 이름은 hello-xxxxx 처럼 무작위 글자가 붙는다
# job/hello 로 부르면 그 Job 의 Pod 로그를 대신 찾아 준다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl create job hello --image=busybox:1.36 -n $NS -- echo ticket-4821-processed >/dev/null 2>&1; kubectl wait --for=condition=complete job/hello -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ -s /tmp/job-log.txt ] ) && ( grep -q \\"ticket-4821-processed\\" /tmp/job-log.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "로그 파일이 비어 있지 않다", "cmd": ["sh", "-c", "[ -s /tmp/job-log.txt ]"]}, {"label": "티켓 번호가 로그에 있다", "cmd": ["sh", "-c", "grep -q \\"ticket-4821-processed\\" /tmp/job-log.txt"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 4, '실패한 Job 의 이유 찾기', 'Job `flaky` 가 실패로 끝났습니다. **Job 의 로그**를 `/tmp/flaky-log.txt` 에 저장하고, 실패한 이유가 무엇인지 읽어 보세요.', '실패해도 Pod 는 남아 있어서 `kubectl logs job/이름` 으로 마지막 출력을 볼 수 있어요. `kubectl get pods` 의 STATUS 도 함께 보세요.', 'kubectl get jobs -n $NS
kubectl get pods -n $NS
kubectl logs job/flaky -n $NS > /tmp/flaky-log.txt
cat /tmp/flaky-log.txt

# 로그에 ''ech0: not found'' 가 보인다: echo 를 ech0 로 잘못 적은 것이다
# 명령이 없으면 Pod 는 Error 로 끝나고, Job 은 실패한 횟수를 센다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: batch/v1\\nkind: Job\\nmetadata:\\n  name: flaky\\nspec:\\n  backoffLimit: 0\\n  template:\\n    spec:\\n      restartPolicy: Never\\n      containers:\\n      - name: main\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"ech0 done\\"]\\nEOF\\ni=0; while [ $i -lt 90 ]; do f=$(kubectl get job flaky -n $NS -o jsonpath=''{.status.failed}'' 2>/dev/null); [ \\"${f:-0}\\" -ge 1 ] && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( [ -s /tmp/flaky-log.txt ] ) && ( grep -q \\"ech0: not found\\" /tmp/flaky-log.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "로그 파일이 저장됐다", "cmd": ["sh", "-c", "[ -s /tmp/flaky-log.txt ]"]}, {"label": "명령을 찾지 못했다는 메시지가 있다", "cmd": ["sh", "-c", "grep -q \\"ech0: not found\\" /tmp/flaky-log.txt"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 5, 'backoffLimit 가 0 이면', 'Job 의 `spec.backoffLimit: 0` 이고 Pod 가 한 번 실패하면 어떻게 될까요?', '`backoffLimit` 는 "다시 시도해 볼 수 있는 횟수"입니다. 기본값은 6 이에요.', NULL, NULL, '[]', 'choice', '["실패해도 성공할 때까지 계속 새 Pod 를 만든다", "Job 이 자동으로 삭제된다", "다시 시도하지 않고 Job 이 바로 실패(Failed)로 표시된다", "Pod 가 실패해도 Job 은 Complete 로 표시된다"]', 2, '`backoffLimit` 는 Pod 가 실패했을 때 새 Pod 로 다시 시도할 수 있는 횟수입니다. 0 이면 재시도 없이 한 번 실패하는 순간 Job 이 Failed 가 됩니다. 기본값 6 이면 간격을 늘려 가며 여섯 번까지 다시 시도하다가 포기해요. 실패한 Job 은 자동으로 지워지지 않고 Pod 와 로그가 남아 있어 원인을 볼 수 있습니다.', NULL, NULL, NULL, NULL),
  (233, 6, '고쳐서 다시 만들기', 'Job `flaky` 는 명령을 `ech0 done` 으로 잘못 적어 실패했습니다. **같은 이름 `flaky` 로, `echo done` 을 실행하도록** 다시 만들어서 성공으로 끝나게 하세요.', 'Job 의 Pod 템플릿(명령)은 만든 뒤에 바꿀 수 없어요. 실패한 Job 을 지운 뒤 다시 만들어야 합니다.', 'kubectl delete job flaky -n $NS
kubectl create job flaky --image=busybox:1.36 -n $NS -- echo done
kubectl get jobs -n $NS
kubectl logs job/flaky -n $NS

# 실패한 Job 은 스스로 고쳐지지 않는다. 템플릿이 고정이라 지우고 새로 만든다
# 지우면 그 Job 의 Pod 도 함께 지워진다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; cat <<EOF | kubectl apply -n $NS -f - >/dev/null 2>&1\\napiVersion: batch/v1\\nkind: Job\\nmetadata:\\n  name: flaky\\nspec:\\n  backoffLimit: 0\\n  template:\\n    spec:\\n      restartPolicy: Never\\n      containers:\\n      - name: main\\n        image: busybox:1.36\\n        command: [\\"sh\\", \\"-c\\", \\"ech0 done\\"]\\nEOF\\ni=0; while [ $i -lt 90 ]; do f=$(kubectl get job flaky -n $NS -o jsonpath=''{.status.failed}'' 2>/dev/null); [ \\"${f:-0}\\" -ge 1 ] && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get job flaky -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 1 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( kubectl logs job/flaky -n $NS 2>/dev/null | grep -q \\"^done$\\" ) && ( [ -z \\"$(kubectl get job flaky -n $NS -o jsonpath=''{.status.failed}'' 2>/dev/null)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "Job flaky 가 성공 1번으로 끝났다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get job flaky -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 1 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "로그가 done 이다", "cmd": ["sh", "-c", "kubectl logs job/flaky -n $NS 2>/dev/null | grep -q \\"^done$\\""]}, {"label": "실패한 흔적이 없는 새 Job 이다", "cmd": ["sh", "-c", "[ -z \\"$(kubectl get job flaky -n $NS -o jsonpath=''{.status.failed}'' 2>/dev/null)\\" ]"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 7, 'completions 와 parallelism 으로 여러 번 실행', 'Job `batch` 를 **YAML 로 만들어** `kubectl apply` 하세요. 이미지는 `busybox:1.36`, 명령은 `echo batch`, 총 **6번 성공**해야 끝나고(`completions`), 한 번에 **2개씩** 실행합니다(`parallelism`). 끝날 때까지 확인하세요.', '`kubectl create job batch --image=busybox:1.36 --dry-run=client -o yaml -- echo batch` 로 뼈대 YAML 을 얻을 수 있어요. `spec` 아래에 두 항목을 더하고 `restartPolicy` 는 `Never` 로 둡니다.', 'cat > /tmp/batch.yaml <<''EOF''
apiVersion: batch/v1
kind: Job
metadata:
  name: batch
spec:
  completions: 6
  parallelism: 2
  template:
    spec:
      restartPolicy: Never
      containers:
      - name: main
        image: busybox:1.36
        command: ["echo", "batch"]
EOF
kubectl apply -n $NS -f /tmp/batch.yaml
kubectl get jobs -n $NS

# completions 는 성공해야 하는 총 횟수, parallelism 은 동시에 띄우는 Pod 수
# COMPLETIONS 칸이 0/6, 2/6, ... 6/6 으로 올라간다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get job batch -n $NS -o jsonpath=''{.spec.completions}'' 2>/dev/null)\\" = 6 ] ) && ( [ \\"$(kubectl get job batch -n $NS -o jsonpath=''{.spec.parallelism}'' 2>/dev/null)\\" = 2 ] ) && ( i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get job batch -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 6 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "completions 가 6 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get job batch -n $NS -o jsonpath=''{.spec.completions}'' 2>/dev/null)\\" = 6 ]"]}, {"label": "parallelism 이 2 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get job batch -n $NS -o jsonpath=''{.spec.parallelism}'' 2>/dev/null)\\" = 2 ]"]}, {"label": "성공이 6번이다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get job batch -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 6 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 8, '끝난 Job 을 자동으로 지우는 필드', '끝난 Job 과 Pod 를 사람이 지우지 않아도, 끝난 지 일정 시간(초)이 지나면 자동으로 지워지게 하는 `spec` 필드가 있습니다. 빈칸에 알맞은 필드를 고르세요.', '이름에 "끝난 뒤(Finished)" 와 "초(Seconds)" 가 들어 있어요.', NULL, NULL, '[]', 'fill', '["ttlSecondsAfterFinished", "activeDeadlineSeconds", "backoffLimit", "parallelism"]', NULL, '`ttlSecondsAfterFinished` 는 Job 이 끝난(성공 또는 실패) 뒤 지정한 초가 지나면 Job 과 딸린 Pod 를 자동으로 지웁니다. 이걸 쓰지 않으면 끝난 Job 이 계속 쌓이므로 정기 작업에는 적어 두는 편이 좋아요. `activeDeadlineSeconds` 는 실행 시간의 상한, `backoffLimit` 는 재시도 횟수, `parallelism` 은 동시 실행 수입니다.', '[0]', '{0}: 100   # Job 이 끝나고 100초 뒤 Job 과 Pod 가 자동으로 삭제된다', NULL, NULL),
  (233, 9, 'CronJob 으로 정해진 때마다 실행', 'CronJob `nightly` 를 만드세요. 이미지는 `busybox:1.36`, 명령은 `echo nightly`, 일정은 **30분마다**(`*/30 * * * *`) 입니다. 만든 뒤 `get cronjob` 으로 SCHEDULE 칸을 확인하세요.', '`kubectl create cronjob 이름 --image=이미지 --schedule="..." -- 명령` 형식입니다. 일정은 따옴표로 감싸세요.', 'kubectl create cronjob nightly --image=busybox:1.36 --schedule="*/30 * * * *" -n $NS -- echo nightly
kubectl get cronjob -n $NS

# 일정은 분 시 일 월 요일 다섯 칸이다. */30 은 30분마다
# CronJob 은 때가 되면 Job 을 만들고, Job 이 Pod 를 만든다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; true"]', '["sh", "-c", "( kubectl get cronjob nightly -n $NS >/dev/null 2>&1 ) && ( [ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.schedule}'' 2>/dev/null)\\" = \\"*/30 * * * *\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "CronJob nightly 가 있다", "cmd": ["sh", "-c", "kubectl get cronjob nightly -n $NS >/dev/null 2>&1"]}, {"label": "일정이 */30 * * * * 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.schedule}'' 2>/dev/null)\\" = \\"*/30 * * * *\\" ]"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 10, 'create job --from 으로 지금 한 번 실행', 'CronJob `nightly` 는 매년 1월 1일에만 돌도록 되어 있습니다. 기다리지 않고 **지금 바로 한 번만** 실행해서 `manual-run` 이라는 Job 이 성공으로 끝나게 하세요. CronJob 의 일정은 바꾸지 않습니다.', '`kubectl create job 새이름 --from=cronjob/이름` 형식입니다. 끝난 뒤 `kubectl logs job/새이름` 으로 결과를 보세요.', 'kubectl create job manual-run --from=cronjob/nightly -n $NS
kubectl get jobs -n $NS
kubectl logs job/manual-run -n $NS

# CronJob 의 jobTemplate 으로 Job 을 하나 즉시 만든다. 일정에는 영향이 없다
# 일정이 먼 CronJob 을 시험해 볼 때 쓴다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl create cronjob nightly --image=busybox:1.36 --schedule=''0 0 1 1 *'' -n $NS -- echo nightly-ok >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get job manual-run -n $NS -o jsonpath=''{.metadata.annotations.cronjob\\\\.kubernetes\\\\.io/instantiate}'' 2>/dev/null)\\" = manual ] ) && ( i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get job manual-run -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 1 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) && ( kubectl logs job/manual-run -n $NS 2>/dev/null | grep -q \\"^nightly-ok$\\" ) && ( [ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.schedule}'' 2>/dev/null)\\" = \\"0 0 1 1 *\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "manual-run 이 CronJob 에서 만든 수동 실행 Job 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get job manual-run -n $NS -o jsonpath=''{.metadata.annotations.cronjob\\\\.kubernetes\\\\.io/instantiate}'' 2>/dev/null)\\" = manual ]"]}, {"label": "manual-run 이 성공 1번으로 끝났다", "cmd": ["sh", "-c", "i=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get job manual-run -n $NS -o jsonpath=''{.status.succeeded}'' 2>/dev/null)\\" = 1 ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]}, {"label": "로그가 nightly-ok 이다", "cmd": ["sh", "-c", "kubectl logs job/manual-run -n $NS 2>/dev/null | grep -q \\"^nightly-ok$\\""]}, {"label": "CronJob 일정은 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.schedule}'' 2>/dev/null)\\" = \\"0 0 1 1 *\\" ]"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 11, 'patch 로 CronJob 잠시 멈추기', '점검 기간 동안 CronJob `nightly` 가 새 Job 을 만들지 않게 **일시 중지**하세요. CronJob 을 지우지 말고 일정도 그대로 둡니다. 중지된 것은 `get cronjob` 의 SUSPEND 칸에서 확인합니다.', '`kubectl patch cronjob 이름 -p ...` 에 JSON 으로 `spec` 아래의 "중지(suspend)" 값을 바꿉니다.', 'kubectl patch cronjob nightly -n $NS -p ''{"spec":{"suspend":true}}''
kubectl get cronjob -n $NS

# SUSPEND 칸이 True 로 바뀐다. 이미 돌고 있는 Job 에는 영향이 없다
# 다시 켜려면 값을 false 로 patch 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml; kubectl delete job hello flaky batch manual-run -n $NS --ignore-not-found --cascade=foreground --wait=true --timeout=60s >/dev/null 2>&1; kubectl delete cronjob nightly -n $NS --ignore-not-found --wait=true --timeout=60s >/dev/null 2>&1; kubectl create cronjob nightly --image=busybox:1.36 --schedule=''0 0 1 1 *'' -n $NS -- echo nightly-ok >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.suspend}'' 2>/dev/null)\\" = true ] ) && ( [ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.schedule}'' 2>/dev/null)\\" = \\"0 0 1 1 *\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "suspend 가 true 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.suspend}'' 2>/dev/null)\\" = true ]"]}, {"label": "일정은 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get cronjob nightly -n $NS -o jsonpath=''{.spec.schedule}'' 2>/dev/null)\\" = \\"0 0 1 1 *\\" ]"]}]', '[{"title": "Job", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/job/"}, {"title": "CronJob", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/cron-jobs/"}, {"title": "kubectl create job", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_create/kubectl_create_job/"}]'),
  (233, 12, '정기 작업을 만들고 시험해 보는 순서', 'CronJob 을 만들어 시험 실행으로 확인하고, 문제가 있으면 멈추는 순서입니다. 순서에 맞게 놓아 보세요.', '만들고 일정을 확인한 뒤, 기다리지 않고 한 번 실행해서 결과를 봅니다. 문제가 있으면 멈추고 시험 Job 은 정리해요.', NULL, NULL, '[]', 'order', '["`kubectl logs job/이름` 으로 시험 실행의 결과를 읽는다", "`kubectl create cronjob ... --schedule=...` 로 CronJob 을 만든다", "`kubectl delete job 이름` 으로 시험으로 만든 Job 을 정리한다", "`kubectl create job 새이름 --from=cronjob/이름` 으로 지금 한 번 실행한다", "`kubectl get cronjob` 으로 SCHEDULE 과 SUSPEND 를 확인한다", "결과가 이상하면 `kubectl patch cronjob 이름 -p ...` 로 suspend 를 true 로 둔다"]', NULL, '먼저 CronJob 을 만들고 `get cronjob` 으로 일정과 SUSPEND 상태를 확인합니다. 때를 기다리지 않고 `create job --from` 으로 한 번 실행해 `logs job/이름` 으로 결과를 읽어요. 결과가 이상하면 patch 로 suspend 를 true 로 두어 새 Job 이 생기지 않게 하고, 시험으로 만든 Job 은 마지막에 지웁니다.', '[1, 4, 3, 0, 5, 2]', NULL, NULL, NULL);
